import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.116.0';
import { CONFIG } from './config.js';

const supabase = createClient(CONFIG.supabaseUrl, CONFIG.supabasePublishableKey, {
  auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true }
});

const root = document.querySelector('#app');
const toastStack = document.createElement('div'); toastStack.className='toast-stack'; document.body.append(toastStack);
const state = {
  session:null, messages:[], accounts:[], labels:[], messageLabels:[], contacts:[], templates:[], signatures:[], settings:null,
  folder:'inbox', category:'all', activeId:null, selected:new Set(), search:'', loading:true,
  composer:null, commandOpen:false, filters:[], realtimeChannel:null
};

const NAV = [
  ['inbox','inbox','Inbox'],['starred','star','Starred'],['snoozed','schedule','Snoozed'],['sent','send','Sent'],
  ['scheduled','calendar_clock','Scheduled'],['drafts','draft','Drafts'],['archive','archive','Archive'],['spam','report','Spam'],['trash','delete','Trash']
];
const CATEGORIES=[['all','All'],['primary','Primary'],['clients','Clients'],['bookings','Bookings'],['finance','Finance']];
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
const stripHtml=(html='')=>{const d=document.createElement('div');d.innerHTML=html;return(d.textContent||d.innerText||'').trim()};
const signaturePlainText=(html='')=>{const d=document.createElement('div');d.innerHTML=String(html).replace(/<br\s*\/?>/gi,'\n');return(d.textContent||d.innerText||'').trim()};
const initials=(name='')=>name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'?';
const arr=v=>Array.isArray(v)?v:[];
const addresses=v=>arr(v).join(', ');
const splitAddr=v=>String(v||'').split(/[;,]/).map(x=>x.trim()).filter(Boolean);
const fmtDate=v=>{if(!v)return'';const d=new Date(v),n=new Date(),diff=n-d;if(d.toDateString()===n.toDateString())return d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});if(diff<7*864e5)return d.toLocaleDateString([], {weekday:'short'});return d.toLocaleDateString([], {day:'2-digit',month:'short'});};
const fmtFull=v=>v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'';
const toast=(msg,icon='check_circle')=>{const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="material-symbols-rounded">${icon}</span><span>${esc(msg)}</span>`;toastStack.append(el);setTimeout(()=>el.remove(),3000)};
const icon=(name,cls='')=>`<span class="material-symbols-rounded ${cls}">${name}</span>`;
const currentUser=()=>state.session?.user;
const accountByAddress=address=>state.accounts.find(a=>a.address===address)||state.accounts.find(a=>a.is_primary)||null;
const accountForMessage=m=>state.accounts.find(a=>a.id===m?.account_id)||accountByAddress(m?.from_address);
const defaultFromAddress=()=>state.accounts.find(a=>a.is_primary)?.address||state.accounts[0]?.address||CONFIG.mailbox;
const trashDaysLeft=m=>{if(!m?.trashed_at)return 10;const ms=new Date(m.trashed_at).getTime()+10*864e5-Date.now();return Math.max(0,Math.ceil(ms/864e5));};
function updateDocumentTitle(){const n=unreadCount();document.title=n?`(${n}) FrankiFlow Mail`:'FrankiFlow Mail';}

function applyTheme(){
  const pref=state.settings?.theme||localStorage.getItem('ffmail-theme')||'system';
  const dark=pref==='dark'||(pref==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);
  document.documentElement.dataset.theme=dark?'dark':'light';
  document.body.dataset.density=state.settings?.density||'comfortable';
}

function loginView(message=''){
  root.innerHTML=`<section class="login"><form class="login-card" id="loginForm"><div class="login-logo">F</div><h1>FrankiFlow Mail</h1><p>A focused workspace for company communication.</p><div class="field"><label>Email</label><input id="email" type="email" value="${esc(CONFIG.mailbox)}" autocomplete="username" required></div><div class="field"><label>Password</label><input id="password" type="password" autocomplete="current-password" required></div><button class="btn-primary" type="submit">${icon('lock_open')} Sign in securely</button><div id="loginError" class="error">${esc(message)}</div></form></section>`;
  document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');const emailEl=document.querySelector('#email'),passwordEl=document.querySelector('#password'),errorEl=document.querySelector('#loginError');b.disabled=true;b.innerHTML=`${icon('progress_activity')} Signing in…`;const {error}=await supabase.auth.signInWithPassword({email:emailEl.value.trim(),password:passwordEl.value});if(error){errorEl.textContent=error.message;b.disabled=false;b.innerHTML=`${icon('lock_open')} Sign in securely`;}};
}

function count(folder){
  if(folder==='starred')return state.messages.filter(m=>m.is_starred&&m.folder!=='trash').length;
  if(folder==='snoozed')return state.messages.filter(m=>m.folder==='snoozed').length;
  return state.messages.filter(m=>m.folder===folder).length;
}
function unreadCount(){return state.messages.filter(m=>m.folder==='inbox'&&!m.is_read).length;}
function labelsFor(id){const ids=state.messageLabels.filter(x=>x.message_id===id).map(x=>x.label_id);return state.labels.filter(l=>ids.includes(l.id));}
function threadFor(m){return m?.thread_id?state.messages.filter(x=>x.thread_id===m.thread_id).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)):[m].filter(Boolean);}
function senderName(m){return m.direction==='outbound'||['sent','scheduled'].includes(m.folder)?addresses(m.to_addresses):(m.from_name||m.from_address||'Unknown');}
function effectiveFolder(m){if(m.folder==='snoozed'&&m.snoozed_until&&new Date(m.snoozed_until)<=new Date())return'inbox';return m.folder;}
function advancedMatch(m,query){
  if(!query.trim())return true;
  const tokens=query.match(/(?:[^\s"]+|"[^"]*")+/g)||[];let free=[];
  const stamp=new Date(m.received_at||m.sent_at||m.created_at||0);
  for(const raw of tokens){
    const t=raw.replace(/^"|"$/g,'');const i=t.indexOf(':');
    if(i>0){
      const k=t.slice(0,i).toLowerCase(),v=t.slice(i+1).toLowerCase();
      if(k==='from'&&!String(m.from_address||'').toLowerCase().includes(v))return false;
      if(k==='to'&&!addresses(m.to_addresses).toLowerCase().includes(v))return false;
      if(k==='subject'&&!String(m.subject||'').toLowerCase().includes(v))return false;
      if(k==='is'&&v==='unread'&&m.is_read)return false;
      if(k==='is'&&v==='read'&&!m.is_read)return false;
      if(k==='is'&&v==='starred'&&!m.is_starred)return false;
      if(k==='is'&&v==='pinned'&&!m.is_pinned)return false;
      if(k==='is'&&v==='important'&&m.priority!=='high')return false;
      if(k==='is'&&v==='muted'&&!m.is_muted)return false;
      if(k==='has'&&v==='attachment'&&!m.has_attachments)return false;
      if(k==='in'&&effectiveFolder(m)!==v)return false;
      if(k==='before'){const d=new Date(v);if(!Number.isNaN(d.getTime())&&stamp>=d)return false;}
      if(k==='after'){const d=new Date(v);if(!Number.isNaN(d.getTime())&&stamp<=d)return false;}
      if(k==='label'){const names=labelsFor(m.id).map(x=>x.name.toLowerCase());if(!names.some(x=>x.includes(v)))return false;}
      continue;
    }
    free.push(t.toLowerCase());
  }
  if(!free.length)return true;
  const hay=[m.from_address,m.from_name,m.subject,m.preview,m.text_body,...arr(m.to_addresses),...arr(m.cc_addresses)].filter(Boolean).join(' ').toLowerCase();
  return free.every(x=>hay.includes(x));
}
function currentMessages(){
  let list=state.folder==='starred'?state.messages.filter(m=>m.is_starred&&m.folder!=='trash'):state.messages.filter(m=>effectiveFolder(m)===state.folder);
  if(state.folder==='inbox'&&state.category!=='all')list=list.filter(m=>(m.category||'primary')===state.category);
  list=list.filter(m=>advancedMatch(m,state.search));
  return list.sort((a,b)=>(b.is_pinned-a.is_pinned)||new Date(b.received_at||b.sent_at||b.created_at)-new Date(a.received_at||a.sent_at||a.created_at));
}

function renderApp(){
  applyTheme();
  const user=currentUser();
  root.innerHTML=`<main class="shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark">F</div><div class="words"><strong>FrankiFlow Mail</strong><small>Mehr als Reinigung.</small></div></div>
      <button class="compose-main" id="composeMain">${icon('edit_square')}<span class="compose-label">Compose</span></button>
      <div class="nav">${NAV.slice(0,6).map(navButton).join('')}</div>
      <div class="nav-section-title">More</div><div class="nav">${NAV.slice(6).map(navButton).join('')}</div>
      <div class="nav-section-title">Labels</div><div class="labels-scroll nav">${state.labels.map(l=>`<button class="nav-btn" data-label="${l.id}"><span class="label-dot" style="background:${esc(l.color)}"></span><span class="nav-label">${esc(l.name)}</span></button>`).join('')||`<button class="nav-btn" id="newLabel">${icon('add')}<span class="nav-label">Create label</span></button>`}</div>
      <div class="sidebar-spacer"></div>
      <div class="account-box"><div class="account-row"><div class="avatar">${initials(user?.email||'FF')}</div><div class="account-email">${esc(user?.email||CONFIG.mailbox)}</div></div><div class="account-actions"><button id="settingsBtn">Settings</button><button id="logoutBtn">Sign out</button></div></div>
    </aside>
    <section class="mail-list">
      <div class="topbar"><div class="search-wrap">${icon('search')}<input id="search" class="search" placeholder="Search mail — try from:, subject:, is:unread, has:attachment" value="${esc(state.search)}"><span class="search-kbd">/</span></div><button class="icon-btn" id="filterBtn" title="Search tips">${icon('tune')}</button><button class="icon-btn" id="notifyBtn" title="Desktop notifications">${icon(typeof Notification!=='undefined'&&Notification.permission==='granted'?'notifications_active':'notifications')}</button><button class="icon-btn" id="refreshBtn" title="Refresh">${icon('refresh')}</button><button class="icon-btn" id="themeBtn" title="Theme">${icon('dark_mode')}</button></div>
      <div class="list-heading"><div class="heading-row"><input class="check" id="selectAll" type="checkbox"><h2>${folderTitle()}</h2><span class="subtle">${currentMessages().length} messages</span></div>${state.folder==='inbox'?`<div class="category-tabs">${CATEGORIES.map(([id,n])=>`<button class="category-tab ${state.category===id?'active':''}" data-category="${id}">${n}</button>`).join('')}</div>`:''}${state.folder==='trash'?`<div class="trash-tools"><span class="subtle">Automatically deleted after 10 days.</span><button class="btn btn-danger-soft" id="emptyTrashBtn">${icon('delete_forever')} Empty trash</button></div>`:''}</div>
      <div id="bulkMount"></div><div class="filter-hint">Tip: press <b>C</b> to compose, <b>J/K</b> to move, <b>E</b> to archive, <b>?</b> for shortcuts.</div>
      <div class="messages" id="messages"></div>
    </section>
    <section class="reader" id="reader"></section>
    <nav class="mobile-nav"><button data-mobile-folder="inbox" class="${state.folder==='inbox'?'active':''}">${icon('inbox')}Inbox</button><button data-mobile-folder="starred" class="${state.folder==='starred'?'active':''}">${icon('star')}Starred</button><button class="mobile-compose" id="mobileCompose">${icon('edit')}</button><button data-mobile-folder="sent" class="${state.folder==='sent'?'active':''}">${icon('send')}Sent</button><button id="mobileMore">${icon('menu')}More</button></nav>
  </main>`;
  wireShell();renderList();renderReader();renderBulk();
}
function navButton([id,ic,label]){const c=id==='inbox'?unreadCount():count(id);return`<button class="nav-btn ${state.folder===id?'active':''}" data-folder="${id}">${icon(ic)}<span class="nav-label">${label}</span>${c?`<span class="count">${c}</span>`:''}</button>`;}
function folderTitle(){return NAV.find(x=>x[0]===state.folder)?.[2]||'Mail';}

function wireShell(){
  document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>switchFolder(b.dataset.folder));
  document.querySelectorAll('[data-mobile-folder]').forEach(b=>b.onclick=()=>switchFolder(b.dataset.mobileFolder));
  document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;renderApp();});
  document.querySelector('#composeMain').onclick=()=>openComposer();document.querySelector('#mobileCompose').onclick=()=>openComposer();
  document.querySelector('#logoutBtn').onclick=()=>supabase.auth.signOut();document.querySelector('#settingsBtn').onclick=openSettings;
  document.querySelector('#notifyBtn').onclick=requestNotifications;document.querySelector('#refreshBtn').onclick=()=>loadAll(true);document.querySelector('#themeBtn').onclick=toggleTheme;document.querySelector('#emptyTrashBtn')?.addEventListener('click',emptyTrash);
  const searchEl=document.querySelector('#search');searchEl.oninput=e=>{state.search=e.target.value;renderList();renderBulk();};
  searchEl.onkeydown=e=>{if(e.key==='Escape'){state.search='';e.target.value='';renderList();}};
  document.querySelector('#selectAll').onchange=e=>{const rows=currentMessages();state.selected.clear();if(e.target.checked)rows.forEach(m=>state.selected.add(m.id));renderList();renderBulk();};
  document.querySelector('#filterBtn').onclick=showSearchHelp;const mobileMore=document.querySelector('#mobileMore');mobileMore.onclick=()=>showPopover(mobileMore,[['Settings','settings',openSettings],['Refresh','refresh',()=>loadAll(true)],['Sign out','logout',()=>supabase.auth.signOut()]]);
  document.querySelectorAll('[data-label]').forEach(b=>b.onclick=()=>{state.search=`label:${state.labels.find(l=>l.id===b.dataset.label)?.name||''}`;switchFolder('inbox');});
  document.querySelector('#newLabel')?.addEventListener('click',()=>openLabelManager(true));
}
function switchFolder(folder){state.folder=folder;state.activeId=null;state.selected.clear();state.category='all';renderApp();}
function toggleTheme(){const cur=state.settings?.theme||'system';const next=cur==='dark'?'light':'dark';saveSettings({theme:next});}

function renderBulk(){
  const mount=document.querySelector('#bulkMount');if(!mount)return;const n=state.selected.size;if(!n){mount.innerHTML='';return;}
  if(state.folder==='trash'){
    mount.innerHTML=`<div class="bulkbar"><span class="selected-count">${n} selected</span><button class="icon-btn" data-bulk="restore" title="Restore to Inbox">${icon('restore_from_trash')}</button><button class="icon-btn btn-danger" data-bulk="deleteForever" title="Delete forever">${icon('delete_forever')}</button></div>`;
  }else{
    mount.innerHTML=`<div class="bulkbar"><span class="selected-count">${n} selected</span><button class="icon-btn" data-bulk="read" title="Mark read">${icon('mark_email_read')}</button><button class="icon-btn" data-bulk="unread" title="Mark unread">${icon('mark_email_unread')}</button><button class="icon-btn" data-bulk="archive" title="Archive">${icon('archive')}</button><button class="icon-btn" data-bulk="snooze" title="Snooze">${icon('schedule')}</button><button class="icon-btn" data-bulk="label" title="Label">${icon('label')}</button><button class="icon-btn btn-danger" data-bulk="trash" title="Trash">${icon('delete')}</button></div>`;
  }
  mount.querySelectorAll('[data-bulk]').forEach(b=>b.onclick=()=>bulkAction(b.dataset.bulk));
}
async function bulkAction(action){
  const ids=[...state.selected];if(!ids.length)return;
  if(action==='label')return openApplyLabel(ids);
  if(action==='snooze')return openSnooze(ids);
  if(action==='deleteForever'){
    if(!confirm(`Delete ${ids.length} message${ids.length>1?'s':''} permanently? This cannot be undone.`))return;
    return hardDeleteMessages(ids);
  }
  const now=new Date().toISOString();let patch={updated_at:now};
  if(action==='read')patch.is_read=true;
  if(action==='unread')patch.is_read=false;
  if(action==='archive'){patch.folder='archive';patch.trashed_at=null;}
  if(action==='trash'){patch.folder='trash';patch.trashed_at=now;}
  if(action==='restore'){patch.folder='inbox';patch.trashed_at=null;}
  const {error}=await supabase.from('frankiflow_mail_messages').update(patch).in('id',ids);
  if(error)return toast(error.message,'error');state.selected.clear();toast(`${ids.length} message${ids.length>1?'s':''} updated`);await loadAll();
}

function renderList(){
  const box=document.querySelector('#messages');if(!box)return;const list=currentMessages();
  if(!list.length){box.innerHTML=`<div class="empty"><div>${icon(state.search?'search_off':'inbox')}<strong>${state.search?'No matching mail':'Nothing here'}</strong>${state.search?'Try another search or remove a filter.':'This folder is clean.'}</div></div>`;return;}
  box.innerHTML=list.map(m=>{const ls=labelsFor(m.id);const th=threadFor(m);return`<article class="mail-row ${m.is_read?'':'unread'} ${state.activeId===m.id?'active':''}" data-id="${m.id}"><input class="check row-check" type="checkbox" ${state.selected.has(m.id)?'checked':''}><button class="star-btn ${m.is_starred?'on':''}" data-star="${m.id}" title="Star">${icon(m.is_starred?'star':'star')}</button><div class="avatar">${initials(senderName(m))}</div><div class="mail-main"><div class="sender-line"><span class="sender">${esc(senderName(m))}</span>${th.length>1?`<span class="thread-count">${th.length}</span>`:''}${m.is_pinned?icon('keep','pin-on'):''}</div><div class="subject-line">${m.priority==='high'?'<span class="priority-dot" title="High priority"></span>':''}<span class="subject">${esc(m.subject||'(no subject)')}</span></div><div class="preview">${esc(m.preview||stripHtml(m.html_body)||m.text_body||'')}</div>${ls.length?`<div class="row-labels">${ls.slice(0,3).map(l=>`<span class="mini-label" style="background:${esc(l.color)}">${esc(l.name)}</span>`).join('')}</div>`:''}</div><div class="row-meta"><time class="time">${fmtDate(m.received_at||m.sent_at||m.scheduled_at||m.created_at)}</time><div class="row-icons">${m.has_attachments?icon('attach_file'):''}${m.folder==='snoozed'?icon('schedule'):''}</div></div></article>`}).join('');
  box.querySelectorAll('.mail-row').forEach(row=>row.onclick=async e=>{if(e.target.closest('.row-check,.star-btn'))return;const m=state.messages.find(x=>x.id===row.dataset.id);if(m?.folder==='drafts'||m?.direction==='draft'){openComposerFromDraft(m);return;}state.activeId=row.dataset.id;if(m&&!m.is_read&&m.direction==='inbound')await patchMessage(m.id,{is_read:true},false);renderList();renderReader();});
  box.querySelectorAll('.row-check').forEach(ch=>ch.onchange=e=>{const id=e.target.closest('.mail-row').dataset.id;e.target.checked?state.selected.add(id):state.selected.delete(id);renderBulk();});
  box.querySelectorAll('[data-star]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const m=state.messages.find(x=>x.id===b.dataset.star);await patchMessage(m.id,{is_starred:!m.is_starred});});
}

function renderReader(){
  const panel=document.querySelector('#reader');if(!panel)return;const m=state.messages.find(x=>x.id===state.activeId);
  if(!m){panel.classList.remove('open');panel.innerHTML=`<div class="reader-empty"><div class="reader-empty-card">${icon('mail')}<strong>Select a conversation</strong>Read, reply, label or organize mail from here.</div></div>`;return;}
  const thread=threadFor(m),ls=labelsFor(m.id);
  panel.classList.add('open');panel.innerHTML=`<div class="reader-head"><button class="icon-btn reader-mobile-back" id="backReader">${icon('arrow_back')}</button><div class="reader-title">${esc(m.subject||'(no subject)')}</div><div class="reader-tools"><button class="icon-btn ${m.is_starred?'active':''}" id="readerStar">${icon('star')}</button><button class="icon-btn" id="readerArchive" title="Archive">${icon('archive')}</button><button class="icon-btn" id="readerSnooze" title="Snooze">${icon('schedule')}</button><button class="icon-btn" id="readerLabel" title="Label">${icon('label')}</button><button class="icon-btn" id="readerMore">${icon('more_vert')}</button></div></div><div class="reader-scroll"><div class="thread-summary"><span class="big-subject">${esc(m.subject||'(no subject)')}</span>${m.priority==='high'?`<span class="chip">${icon('priority_high')} Important</span>`:''}${ls.map(l=>`<span class="chip"><span class="label-dot" style="background:${esc(l.color)}"></span>${esc(l.name)}</span>`).join('')}</div>${thread.map(renderThreadCard).join('')}${m.folder!=='trash'?quickReplyHtml(m):''}</div>`;
  document.querySelector('#backReader').onclick=()=>panel.classList.remove('open');document.querySelector('#readerStar').onclick=()=>patchMessage(m.id,{is_starred:!m.is_starred});
  const archiveBtn=document.querySelector('#readerArchive'),snoozeBtn=document.querySelector('#readerSnooze');
  if(m.folder==='trash'){
    archiveBtn.title='Restore to Inbox';archiveBtn.innerHTML=icon('restore_from_trash');archiveBtn.onclick=()=>moveMessage(m.id,'inbox');
    snoozeBtn.title='Delete forever';snoozeBtn.innerHTML=icon('delete_forever');snoozeBtn.onclick=()=>{if(confirm('Delete this message permanently? This cannot be undone.'))hardDeleteMessages([m.id]);};
  }else{
    archiveBtn.onclick=()=>moveMessage(m.id,'archive');snoozeBtn.onclick=()=>openSnooze([m.id]);
  }
  document.querySelector('#readerLabel').onclick=()=>openApplyLabel([m.id]);
  const moreBtn=document.querySelector('#readerMore');
  moreBtn.onclick=()=>showPopover(moreBtn,m.folder==='trash'?
    [['Restore to Inbox','restore_from_trash',()=>moveMessage(m.id,'inbox')],['Print','print',()=>window.print()],['Delete forever','delete_forever',()=>{if(confirm('Delete this message permanently? This cannot be undone.'))hardDeleteMessages([m.id]);},true]]:
    [['Mark unread','mark_email_unread',()=>patchMessage(m.id,{is_read:false})],[m.is_pinned?'Unpin':'Pin','keep',()=>patchMessage(m.id,{is_pinned:!m.is_pinned})],[m.priority==='high'?'Normal priority':'High priority','priority_high',()=>patchMessage(m.id,{priority:m.priority==='high'?'normal':'high'})],['Category: Clients','group',()=>patchMessage(m.id,{category:'clients'})],['Category: Bookings','hotel',()=>patchMessage(m.id,{category:'bookings'})],['Category: Finance','payments',()=>patchMessage(m.id,{category:'finance'})],[m.folder==='spam'?'Not spam':'Move to spam',m.folder==='spam'?'inbox':'report',()=>moveMessage(m.id,m.folder==='spam'?'inbox':'spam')],['Print','print',()=>window.print()],['Delete','delete',()=>moveMessage(m.id,'trash'),true]]);
  document.querySelector('#replySend')?.addEventListener('click',()=>sendQuickReply(m));
  document.querySelector('#replyCompose')?.addEventListener('click',()=>openComposer({fromAddress:accountForMessage(m)?.address||defaultFromAddress(),to:m.reply_to||m.from_address,subject:replySubject(m.subject),thread_id:m.thread_id,in_reply_to:m.provider_message_id}));
  document.querySelector('#replyAllBtn')?.addEventListener('click',()=>{
    const own=new Set(state.accounts.map(a=>a.address.toLowerCase()));
    const primary=(m.reply_to||m.from_address||'').toLowerCase();
    const cc=[...arr(m.to_addresses),...arr(m.cc_addresses)].map(x=>String(x).trim()).filter(Boolean).filter(x=>!own.has(x.toLowerCase())&&x.toLowerCase()!==primary);
    openComposer({fromAddress:accountForMessage(m)?.address||defaultFromAddress(),to:m.reply_to||m.from_address,cc:[...new Set(cc)].join(', '),subject:replySubject(m.subject),thread_id:m.thread_id,in_reply_to:m.provider_message_id});
  });
  document.querySelector('#forwardBtn')?.addEventListener('click',()=>openComposer({subject:`Fwd: ${m.subject||''}`,text:`\n\n---------- Forwarded message ----------\nFrom: ${m.from_name||m.from_address}\nDate: ${fmtFull(m.received_at||m.created_at)}\nSubject: ${m.subject||''}\n\n${m.text_body||''}`}));
}
function renderThreadCard(x){return`<article class="thread-card"><div class="thread-card-head"><div class="avatar">${initials(x.from_name||x.from_address)}</div><div class="who"><strong>${esc(x.from_name||x.from_address)}</strong><div class="meta">${esc(x.from_address)} → ${esc(addresses(x.to_addresses))}${arr(x.cc_addresses).length?` · cc ${esc(addresses(x.cc_addresses))}`:''}</div></div><time>${fmtFull(x.received_at||x.sent_at||x.created_at)}</time></div><div class="thread-body">${esc(x.text_body||stripHtml(x.html_body)||'').replace(/\n/g,'<br>')}</div></article>`;}
function quickReplyHtml(m){return`<div class="quick-reply"><div class="quick-reply-head"><strong>Reply</strong><div><button class="icon-btn" id="replyAllBtn" title="Reply all">${icon('reply_all')}</button><button class="icon-btn" id="forwardBtn" title="Forward">${icon('forward')}</button></div></div><div id="quickReplyEditor" class="quick-reply-editor" contenteditable="true" data-placeholder="Write a quick reply…"></div><div class="quick-actions"><button class="btn" id="replyCompose">${icon('open_in_full')} Full composer</button><button class="btn-primary" id="replySend">${icon('send')} Reply</button></div></div>`;}
const replySubject=s=>/^re:/i.test(s||'')?s:`Re: ${s||''}`;
async function sendQuickReply(m){const editor=document.querySelector('#quickReplyEditor');const html=editor.innerHTML.trim(),text=editor.innerText.trim();if(!text)return;const ok=await sendMail({fromAddress:accountForMessage(m)?.address||defaultFromAddress(),to:m.reply_to||m.from_address,subject:replySubject(m.subject),text,html,thread_id:m.thread_id,in_reply_to:m.provider_message_id});if(ok)editor.innerHTML='';}

async function patchMessage(id,patch,rerender=true){const {error}=await supabase.from('frankiflow_mail_messages').update({...patch,updated_at:new Date().toISOString()}).eq('id',id);if(error)return toast(error.message,'error');Object.assign(state.messages.find(x=>x.id===id)||{},patch);if(rerender)renderApp();}
async function moveMessage(id,folder){const patch={folder,trashed_at:folder==='trash'?new Date().toISOString():null};await patchMessage(id,patch);state.activeId=null;toast(folder==='inbox'?'Restored to Inbox':`Moved to ${folder}`);await loadAll();}
async function hardDeleteMessages(ids){
  if(!ids?.length)return;
  const {data:attachments,error:attachmentError}=await supabase.from('frankiflow_mail_attachments').select('storage_path').in('message_id',ids);
  if(attachmentError)return toast(attachmentError.message,'error');
  const paths=(attachments||[]).map(x=>x.storage_path).filter(Boolean);
  if(paths.length){const {error:storageError}=await supabase.storage.from('frankiflow-mail-attachments').remove(paths);if(storageError)return toast(storageError.message,'error');}
  const {error}=await supabase.from('frankiflow_mail_messages').delete().in('id',ids);if(error)return toast(error.message,'error');
  ids.forEach(id=>state.selected.delete(id));if(ids.includes(state.activeId))state.activeId=null;toast(`${ids.length} message${ids.length>1?'s':''} permanently deleted`,'delete_forever');await loadAll();
}
async function emptyTrash(){const ids=state.messages.filter(m=>m.folder==='trash').map(m=>m.id);if(!ids.length)return toast('Trash is already empty','delete');if(!confirm(`Permanently delete all ${ids.length} messages in Trash?`))return;await hardDeleteMessages(ids);}

function openComposer(seed={}){
  closePopover();if(state.composer?.el)state.composer.el.remove();const el=document.createElement('section');el.className='composer';
  el.innerHTML=`<div class="composer-head"><strong>${seed.draftId?'Draft':'New message'}</strong><button data-c-action="min" title="Minimize">${icon('remove')}</button><button data-c-action="max" title="Expand">${icon('open_in_full')}</button><button data-c-action="close" title="Close">${icon('close')}</button></div><div class="composer-body"><div class="address-row"><label>From</label><select id="cFrom">${state.accounts.map(a=>`<option value="${esc(a.address)}" ${(seed.fromAddress||defaultFromAddress())===a.address?'selected':''}>${esc(a.display_name||'FrankiFlow')} · ${esc(a.address)}</option>`).join('')}</select></div><div class="address-row"><label>To</label><input id="cTo" list="contactSuggestions" value="${esc(seed.to||'')}" placeholder="Recipients"><datalist id="contactSuggestions">${state.contacts.map(c=>`<option value="${esc(c.email)}">${esc(c.display_name||c.email)}</option>`).join('')}</datalist><span class="address-links"><a id="showCc">Cc</a><a id="showBcc">Bcc</a></span></div><div class="address-row hidden" id="ccRow"><label>Cc</label><input id="cCc" value="${esc(seed.cc||'')}"></div><div class="address-row hidden" id="bccRow"><label>Bcc</label><input id="cBcc" value="${esc(seed.bcc||'')}"></div><div class="address-row subject-row"><label>Subject</label><input id="cSubject" value="${esc(seed.subject||'')}" placeholder="Subject"></div><div class="composer-toolbar"><button class="toolbar-btn" data-format="bold" title="Bold">${icon('format_bold')}</button><button class="toolbar-btn" data-format="italic" title="Italic">${icon('format_italic')}</button><button class="toolbar-btn" data-format="underline" title="Underline">${icon('format_underlined')}</button><span class="toolbar-sep"></span><button class="toolbar-btn" data-format="insertUnorderedList">${icon('format_list_bulleted')}</button><button class="toolbar-btn" data-format="insertOrderedList">${icon('format_list_numbered')}</button><button class="toolbar-btn" id="linkBtn">${icon('link')}</button><span class="toolbar-sep"></span><button class="toolbar-btn" id="templateBtn" title="Templates">${icon('article')}</button><button class="toolbar-btn" id="signatureBtn" title="Signature">${icon('draw')}</button></div><div id="cEditor" class="composer-editor" contenteditable="true" data-placeholder="Write your message…">${seed.html||esc(seed.text||'').replace(/\n/g,'<br>')}</div><div class="composer-attachments" id="attachmentList"></div></div><div class="composer-foot"><div class="send-group"><button class="btn-primary" id="sendNow">${icon('send')} Send</button><button class="send-menu-btn" id="sendMenu">${icon('arrow_drop_down')}</button></div><button class="icon-btn" id="attachBtn" title="Attach file">${icon('attach_file')}</button><input id="fileInput" type="file" multiple class="hidden"><span class="draft-status" id="draftStatus">${seed.draftId?'Draft loaded':'Autosave on'}</span><span class="composer-foot-spacer"></span><button class="icon-btn" id="discardDraft" title="Discard">${icon('delete')}</button></div>`;
  document.body.append(el);state.composer={el,seed,files:[],draftId:seed.draftId||null,saveTimer:null,selectedSignatureId:null};
  if(state.settings?.signature_enabled!==false&&!seed.draftId&&!seed.html&&!seed.text)insertDefaultSignature();
  el.querySelector('[data-c-action="close"]').onclick=()=>closeComposer();el.querySelector('[data-c-action="min"]').onclick=()=>el.classList.toggle('minimized');el.querySelector('[data-c-action="max"]').onclick=()=>el.classList.toggle('maximized');
  el.querySelector('#showCc').onclick=()=>el.querySelector('#ccRow').classList.remove('hidden');el.querySelector('#showBcc').onclick=()=>el.querySelector('#bccRow').classList.remove('hidden');
  const editor=el.querySelector('#cEditor');el.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{document.execCommand(b.dataset.format,false,null);editor.focus();});
  const linkButton=el.querySelector('#linkBtn'),templateButton=el.querySelector('#templateBtn'),signatureButton=el.querySelector('#signatureBtn');linkButton.onclick=()=>{const u=prompt('Paste link URL');if(u)document.execCommand('createLink',false,u)};templateButton.onclick=()=>showTemplatePicker(templateButton);signatureButton.onclick=()=>showSignaturePicker(signatureButton);el.querySelector('#cFrom').onchange=()=>{syncDefaultSignature();scheduleAutosave();};
  const attachButton=el.querySelector('#attachBtn'),fileInputEl=el.querySelector('#fileInput'),sendNowBtn=el.querySelector('#sendNow'),sendMenuBtn=el.querySelector('#sendMenu');attachButton.onclick=()=>fileInputEl.click();fileInputEl.onchange=()=>addFiles([...fileInputEl.files]);sendNowBtn.onclick=()=>sendComposer();sendMenuBtn.onclick=()=>showSendMenu(sendMenuBtn);
  el.querySelector('#discardDraft').onclick=()=>discardComposer();['cTo','cCc','cBcc','cSubject'].forEach(id=>el.querySelector(`#${id}`)?.addEventListener('input',scheduleAutosave));editor.addEventListener('input',scheduleAutosave);
}
function openComposerFromDraft(m){openComposer({draftId:m.id,fromAddress:m.from_address,to:addresses(m.to_addresses),cc:addresses(m.cc_addresses),bcc:addresses(m.bcc_addresses),subject:m.subject,html:m.html_body||esc(m.text_body||'').replace(/\n/g,'<br>'),thread_id:m.thread_id});}
async function closeComposer(){if(!state.composer)return;await saveDraft();state.composer?.el.remove();state.composer=null;}
async function discardComposer(){const d=state.composer?.draftId;if(d)await supabase.from('frankiflow_mail_messages').delete().eq('id',d);state.composer?.el.remove();state.composer=null;toast('Draft discarded','delete');await loadAll();}
function composerData(){const c=state.composer?.el;if(!c)return null;return{fromAddress:c.querySelector('#cFrom').value,to:c.querySelector('#cTo').value,cc:c.querySelector('#cCc').value,bcc:c.querySelector('#cBcc').value,subject:c.querySelector('#cSubject').value,html:c.querySelector('#cEditor').innerHTML,text:c.querySelector('#cEditor').innerText,thread_id:state.composer.seed.thread_id||null,in_reply_to:state.composer.seed.in_reply_to||null};}
function defaultSignatureFor(address){const account=accountByAddress(address);return state.signatures.find(s=>s.is_default&&s.account_id===account?.id)||state.signatures.find(s=>s.is_default&&!s.account_id)||null;}
function insertSignature(signatureId=null){const ed=state.composer?.el.querySelector('#cEditor');if(!ed)return;ed.querySelectorAll('.signature[data-ff-signature]').forEach(x=>x.remove());const sig=signatureId?state.signatures.find(s=>s.id===signatureId):defaultSignatureFor(state.composer?.el.querySelector('#cFrom')?.value);const html=sig?.html_body||(!state.signatures.length?state.settings?.signature_html:'');if(!html)return;if(ed.innerHTML&&!ed.innerHTML.endsWith('<br>'))ed.innerHTML+='<br><br>';ed.innerHTML+=`<div class="signature" data-ff-signature="${esc(sig?.id||'legacy')}">${html}</div>`;if(state.composer)state.composer.selectedSignatureId=sig?.id||'legacy';scheduleAutosave();}
function insertDefaultSignature(){insertSignature();}
function syncDefaultSignature(){if(state.composer?.el.querySelector('#cEditor .signature[data-ff-signature]'))insertSignature();}
function showSignaturePicker(anchor){const items=state.signatures.map(s=>[`${s.name}${s.is_default?' · default':''}`,'draw',()=>insertSignature(s.id)]);items.push(['Remove signature','format_clear',()=>{state.composer?.el.querySelectorAll('#cEditor .signature[data-ff-signature]').forEach(x=>x.remove());scheduleAutosave();}]);items.push(['Manage signatures','settings',()=>openSignatureManager()]);showPopover(anchor,items);}
function openSignatureManager(){
  const accountOptions=`<option value="">All senders</option>${state.accounts.map(a=>`<option value="${a.id}">${esc(a.address)}</option>`).join('')}`;
  const content=`<div id="signatureList">${state.signatures.map(s=>`<div class="template-item" data-sig-row="${s.id}"><div class="main"><strong>${esc(s.name)}${s.is_default?' · Default':''}</strong><small>${esc(stripHtml(s.html_body)).slice(0,80)}</small></div><button class="icon-btn" data-sig-edit="${s.id}">${icon('edit')}</button><button class="icon-btn" data-sig-delete="${s.id}">${icon('delete')}</button></div>`).join('')||'<p class="muted">No signatures yet.</p>'}</div><input id="sigId" type="hidden"><div class="field"><label>Name</label><input id="sigName" placeholder="FrankiFlow standard"></div><div class="field"><label>Use for sender</label><select id="sigAccount">${accountOptions}</select></div><div class="field"><label>Signature</label><textarea id="sigBody" rows="6" placeholder="Best regards,\nFrankiFlow"></textarea></div><label class="setting-row"><div><strong>Default signature</strong><small>Insert automatically for this sender.</small></div><input id="sigDefault" type="checkbox"></label>`;
  openModal('Signatures',content,async modal=>{
    const id=modal.querySelector('#sigId').value,name=modal.querySelector('#sigName').value.trim(),body=modal.querySelector('#sigBody').value,accountId=modal.querySelector('#sigAccount').value||null,isDefault=modal.querySelector('#sigDefault').checked;if(!name||!body.trim())return toast('Add a signature name and text','warning');
    if(isDefault){let q=supabase.from('frankiflow_mail_signatures').update({is_default:false,updated_at:new Date().toISOString()}).eq('user_id',currentUser().id);q=accountId?q.eq('account_id',accountId):q.is('account_id',null);await q;}
    const row={user_id:currentUser().id,account_id:accountId,name,html_body:esc(body).replace(/\n/g,'<br>'),is_default:isDefault,updated_at:new Date().toISOString()};const result=id?await supabase.from('frankiflow_mail_signatures').update(row).eq('id',id):await supabase.from('frankiflow_mail_signatures').insert(row);if(result.error)return toast(result.error.message,'error');modal.closest('.modal-backdrop').remove();await loadAll();toast(id?'Signature updated':'Signature created','draw');
  },modal=>{
    modal.querySelectorAll('[data-sig-edit]').forEach(b=>b.onclick=()=>{const s=state.signatures.find(x=>x.id===b.dataset.sigEdit);if(!s)return;modal.querySelector('#sigId').value=s.id;modal.querySelector('#sigName').value=s.name;modal.querySelector('#sigAccount').value=s.account_id||'';modal.querySelector('#sigBody').value=signaturePlainText(s.html_body);modal.querySelector('#sigDefault').checked=s.is_default;});
    modal.querySelectorAll('[data-sig-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this signature?'))return;const {error}=await supabase.from('frankiflow_mail_signatures').delete().eq('id',b.dataset.sigDelete);if(error)return toast(error.message,'error');b.closest('[data-sig-row]')?.remove();state.signatures=state.signatures.filter(s=>s.id!==b.dataset.sigDelete);});
  });
}
function addFiles(files){const allowed=files.filter(f=>f.size<=8*1024*1024);const total=[...state.composer.files,...allowed].reduce((s,f)=>s+f.size,0);if(total>18*1024*1024)return toast('Keep total attachments under 18 MB','warning');state.composer.files.push(...allowed);if(allowed.length<files.length)toast('Files over 8 MB were skipped','warning');renderAttachments();}
function renderAttachments(){const box=state.composer?.el.querySelector('#attachmentList');if(!box)return;box.innerHTML=state.composer.files.map((f,i)=>`<span class="file-pill">${icon('description')} ${esc(f.name)} <small>${(f.size/1024/1024).toFixed(1)} MB</small><button data-file-remove="${i}">${icon('close')}</button></span>`).join('');box.querySelectorAll('[data-file-remove]').forEach(b=>b.onclick=()=>{state.composer.files.splice(+b.dataset.fileRemove,1);renderAttachments();});}
function scheduleAutosave(immediate=false){if(!state.composer)return;clearTimeout(state.composer.saveTimer);state.composer.el.querySelector('#draftStatus').textContent='Saving…';state.composer.saveTimer=setTimeout(saveDraft,immediate?0:900);}
async function saveDraft(){if(!state.composer)return;const d=composerData();if(!d)return;if(!state.composer.draftId&&!d.to.trim()&&!d.cc.trim()&&!d.bcc.trim()&&!d.subject.trim()&&!d.text.trim()){state.composer.el.querySelector('#draftStatus').textContent='Autosave on';return;}const account=accountByAddress(d.fromAddress)||await primaryAccount();const row={account_id:account.id,thread_id:d.thread_id,direction:'draft',folder:'drafts',from_address:d.fromAddress,to_addresses:splitAddr(d.to),cc_addresses:splitAddr(d.cc),bcc_addresses:splitAddr(d.bcc),subject:d.subject||'',text_body:d.text||'',html_body:d.html||'',preview:(d.text||'').replace(/\s+/g,' ').slice(0,180),is_read:true,updated_at:new Date().toISOString()};let result;if(state.composer.draftId)result=await supabase.from('frankiflow_mail_messages').update(row).eq('id',state.composer.draftId);else result=await supabase.from('frankiflow_mail_messages').insert(row).select('id').single();if(result.error)return state.composer?.el.querySelector('#draftStatus')&&(state.composer.el.querySelector('#draftStatus').textContent='Save failed');if(result.data?.id)state.composer.draftId=result.data.id;if(state.composer)state.composer.el.querySelector('#draftStatus').textContent='Saved';}
async function filePayload(){const out=[];for(const f of state.composer?.files||[]){const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});out.push({filename:f.name,content,contentType:f.type||undefined});}return out;}
async function sendComposer(scheduledAt=null){const d=composerData();if(!d?.to.trim())return toast('Add at least one recipient','warning');const b=state.composer.el.querySelector('#sendNow');b.disabled=true;b.innerHTML=`${icon('progress_activity')} Sending`;const attachments=await filePayload();const ok=await sendMail({...d,scheduledAt,attachments,draft_id:state.composer.draftId});if(ok){state.composer.el.remove();state.composer=null;}else{b.disabled=false;b.innerHTML=`${icon('send')} Send`;}}
function showSendMenu(anchor){showPopover(anchor,[['Send now','send',()=>sendComposer()],['Later today','schedule',()=>sendComposer(todayAt(18))],['Tomorrow morning','calendar_today',()=>sendComposer(tomorrowAt(8))],['Choose date & time','edit_calendar',()=>openSchedulePicker()]]);}
function todayAt(h){const d=new Date();d.setHours(h,0,0,0);if(d<=new Date())d.setDate(d.getDate()+1);return d.toISOString();}function tomorrowAt(h){const d=new Date();d.setDate(d.getDate()+1);d.setHours(h,0,0,0);return d.toISOString();}
function openSchedulePicker(){closePopover();const d=new Date(Date.now()+3600e3);const local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);openModal('Schedule send',`<div class="field"><label>Send date and time</label><input id="scheduleAt" type="datetime-local" value="${local}" min="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}"></div>`,async modal=>{const v=modal.querySelector('#scheduleAt').value;if(!v)return;modal.closest('.modal-backdrop').remove();await sendComposer(new Date(v).toISOString());});}

async function sendMail(payload){
  try{const {data,error}=await supabase.functions.invoke('send-mail',{body:{...payload,to:splitAddr(payload.to),cc:splitAddr(payload.cc),bcc:splitAddr(payload.bcc)}});if(error)throw error;if(data?.error)throw new Error(data.error);if(payload.draft_id)await supabase.from('frankiflow_mail_messages').delete().eq('id',payload.draft_id);await rememberContacts(splitAddr(payload.to));toast(payload.scheduledAt?'Email scheduled':'Email sent',payload.scheduledAt?'schedule':'send');await loadAll();return true;}catch(e){toast(`Send failed: ${e.message}`,'error');return false;}
}
async function rememberContacts(emails){for(const email of emails){const existing=state.contacts.find(c=>c.email.toLowerCase()===email.toLowerCase());if(existing)await supabase.from('frankiflow_mail_contacts').update({use_count:(existing.use_count||0)+1,last_used_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq('id',existing.id);else await supabase.from('frankiflow_mail_contacts').insert({email,use_count:1,last_used_at:new Date().toISOString()});}}
async function primaryAccount(){const {data,error}=await supabase.from('frankiflow_mail_accounts').select('*').eq('is_primary',true).single();if(error)throw error;return data;}

function openSnooze(ids){openModal('Snooze message',`<div class="field"><label>Bring it back</label><select id="snoozeChoice"><option value="later">Later today · 18:00</option><option value="tomorrow">Tomorrow · 08:00</option><option value="week">Next week · Monday 08:00</option><option value="custom">Choose date & time</option></select></div><div class="field hidden" id="snoozeCustomWrap"><label>Date and time</label><input id="snoozeCustom" type="datetime-local"></div>`,async modal=>{const c=modal.querySelector('#snoozeChoice').value;let d;if(c==='later')d=new Date(todayAt(18));if(c==='tomorrow')d=new Date(tomorrowAt(8));if(c==='week'){d=new Date();d.setDate(d.getDate()+((8-d.getDay())%7||7));d.setHours(8,0,0,0);}if(c==='custom')d=new Date(modal.querySelector('#snoozeCustom').value);if(!d||isNaN(d))return;const {error}=await supabase.from('frankiflow_mail_messages').update({folder:'snoozed',snoozed_until:d.toISOString(),updated_at:new Date().toISOString()}).in('id',ids);if(error)return toast(error.message,'error');modal.closest('.modal-backdrop').remove();state.selected.clear();state.activeId=null;toast('Message snoozed','schedule');await loadAll();},modal=>{modal.querySelector('#snoozeChoice').onchange=e=>modal.querySelector('#snoozeCustomWrap').classList.toggle('hidden',e.target.value!=='custom');});}

function openApplyLabel(ids){const body=`<div>${state.labels.map(l=>`<label class="label-manage-item"><input class="check label-choice" type="checkbox" value="${l.id}"><span class="label-dot" style="background:${esc(l.color)}"></span><span>${esc(l.name)}</span></label>`).join('')||'<p class="muted">No labels yet.</p>'}<button class="btn" id="manageLabelsInline">${icon('add')} Create label</button></div>`;openModal('Apply labels',body,async modal=>{const choices=[...modal.querySelectorAll('.label-choice:checked')].map(x=>x.value);for(const id of ids){for(const label_id of choices)await supabase.from('frankiflow_mail_message_labels').upsert({message_id:id,label_id},{onConflict:'message_id,label_id'});}modal.closest('.modal-backdrop').remove();toast('Labels updated','label');await loadAll();},modal=>modal.querySelector('#manageLabelsInline').onclick=()=>{modal.closest('.modal-backdrop').remove();openLabelManager(true);});}
function openLabelManager(create=false){const content=`<div id="labelList">${state.labels.map(l=>`<div class="label-manage-item"><span class="label-dot" style="background:${esc(l.color)}"></span><span style="flex:1">${esc(l.name)}</span><button class="icon-btn" data-label-delete="${l.id}">${icon('delete')}</button></div>`).join('')}</div><div class="field"><label>New label</label><input id="labelName" placeholder="e.g. Clients"><input id="labelColor" type="color" value="#155b74"></div>`;openModal('Manage labels',content,async modal=>{const name=modal.querySelector('#labelName').value.trim();if(name){const {error}=await supabase.from('frankiflow_mail_labels').insert({name,color:modal.querySelector('#labelColor').value,created_by:currentUser().id});if(error)return toast(error.message,'error');}modal.closest('.modal-backdrop').remove();await loadAll();toast(name?'Label created':'Labels saved','label');},modal=>{modal.querySelectorAll('[data-label-delete]').forEach(b=>b.onclick=async()=>{await supabase.from('frankiflow_mail_labels').delete().eq('id',b.dataset.labelDelete);b.closest('.label-manage-item').remove();});if(create)setTimeout(()=>modal.querySelector('#labelName').focus(),30);});}

function showTemplatePicker(anchor){if(!state.templates.length)return showPopover(anchor,[['No templates yet','article',()=>openTemplateManager()],['Create template','add',()=>openTemplateManager(true)]]);showPopover(anchor,[...state.templates.map(t=>[t.name,'article',()=>applyTemplate(t)]),['Manage templates','settings',()=>openTemplateManager()]]);}
function applyTemplate(t){const c=state.composer?.el;if(!c)return;c.querySelector('#cSubject').value=t.subject||c.querySelector('#cSubject').value;c.querySelector('#cEditor').innerHTML=t.html_body||esc(t.text_body||'').replace(/\n/g,'<br>');if(state.settings?.signature_enabled!==false)insertSignature();scheduleAutosave();}
function openTemplateManager(create=false){const content=`<div>${state.templates.map(t=>`<div class="template-item"><div class="main"><strong>${esc(t.name)}</strong><small>${esc(t.subject||t.text_body||'')}</small></div><button class="icon-btn" data-template-delete="${t.id}">${icon('delete')}</button></div>`).join('')}</div><div class="field"><label>Template name</label><input id="tplName" placeholder="Quote follow-up"></div><div class="field"><label>Subject</label><input id="tplSubject"></div><div class="field"><label>Message</label><textarea id="tplBody" rows="6"></textarea></div>`;openModal('Email templates',content,async modal=>{const name=modal.querySelector('#tplName').value.trim();if(name){const {error}=await supabase.from('frankiflow_mail_templates').insert({name,subject:modal.querySelector('#tplSubject').value,text_body:modal.querySelector('#tplBody').value,created_by:currentUser().id});if(error)return toast(error.message,'error');}modal.closest('.modal-backdrop').remove();await loadAll();if(name)toast('Template created','article');},modal=>{modal.querySelectorAll('[data-template-delete]').forEach(b=>b.onclick=async()=>{await supabase.from('frankiflow_mail_templates').delete().eq('id',b.dataset.templateDelete);b.closest('.template-item').remove();});if(create)setTimeout(()=>modal.querySelector('#tplName').focus(),30);});}

function openFilterManager(){const filters=state.filters||[];const content=`<div>${filters.map(f=>`<div class="template-item"><div class="main"><strong>${esc(f.name)}</strong><small>${esc(filterSummary(f))}</small></div><button class="icon-btn" data-filter-delete="${f.id}">${icon('delete')}</button></div>`).join('')||'<p class="muted">No filters yet. Create one to organize incoming mail automatically when you open the mailbox.</p>'}</div><div class="field"><label>Filter name</label><input id="filterName" placeholder="Invoices"></div><div class="field"><label>From contains</label><input id="filterFrom" placeholder="@client.com or billing@"></div><div class="field"><label>Subject contains</label><input id="filterSubject" placeholder="invoice"></div><div class="field"><label>Action</label><select id="filterAction"><option value="category:clients">Category · Clients</option><option value="category:bookings">Category · Bookings</option><option value="category:finance">Category · Finance</option><option value="folder:archive">Move · Archive</option><option value="is_read:true">Mark · Read</option><option value="is_starred:true">Mark · Starred</option></select></div>`;openModal('Mail filters',content,async modal=>{const name=modal.querySelector('#filterName').value.trim();if(name){const [field,value]=modal.querySelector('#filterAction').value.split(':');const conditions={from_contains:modal.querySelector('#filterFrom').value.trim(),subject_contains:modal.querySelector('#filterSubject').value.trim()};const actions={[field]:value==='true'?true:value};const {error}=await supabase.from('frankiflow_mail_filters').insert({name,conditions,actions,created_by:currentUser().id});if(error)return toast(error.message,'error');}modal.closest('.modal-backdrop').remove();await loadAll();if(name){await applyFilters();toast('Filter created','filter_alt');}},modal=>modal.querySelectorAll('[data-filter-delete]').forEach(b=>b.onclick=async()=>{await supabase.from('frankiflow_mail_filters').delete().eq('id',b.dataset.filterDelete);b.closest('.template-item').remove();}));}
function filterSummary(f){const c=f.conditions||{},a=f.actions||{};return`${c.from_contains?`from contains “${c.from_contains}” `:''}${c.subject_contains?`subject contains “${c.subject_contains}” `:''}→ ${Object.entries(a).map(([k,v])=>`${k}=${v}`).join(', ')}`;}
async function applyFilters(){if(!state.filters?.length)return;for(const m of state.messages.filter(x=>x.direction==='inbound'&&x.folder==='inbox')){for(const f of state.filters.filter(x=>x.active!==false)){const c=f.conditions||{};if(c.from_contains&&!String(m.from_address||'').toLowerCase().includes(String(c.from_contains).toLowerCase()))continue;if(c.subject_contains&&!String(m.subject||'').toLowerCase().includes(String(c.subject_contains).toLowerCase()))continue;const patch={};for(const [k,v] of Object.entries(f.actions||{}))patch[k]=v;if(Object.keys(patch).length){await supabase.from('frankiflow_mail_messages').update({...patch,updated_at:new Date().toISOString()}).eq('id',m.id);Object.assign(m,patch);}}}}

function openSettings(){const s=state.settings||{};const notificationState=typeof Notification==='undefined'?'Unsupported':Notification.permission;const content=`<div class="setting-row"><div><strong>Theme</strong><small>Use light, dark or your device preference.</small></div><select id="setTheme"><option value="system">System</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="setting-row"><div><strong>Density</strong><small>Control how much mail fits on screen.</small></div><select id="setDensity"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><div class="setting-row"><div><strong>Keyboard shortcuts</strong><small>C to compose, J/K navigate, E archive and more.</small></div><select id="setShortcuts"><option value="true">Enabled</option><option value="false">Disabled</option></select></div><div class="setting-row"><div><strong>Automatic signature</strong><small>Insert the default signature for the selected sender.</small></div><select id="setSignatureEnabled"><option value="true">Enabled</option><option value="false">Disabled</option></select></div><div class="setting-row"><div><strong>Desktop notifications</strong><small>Current status: ${esc(notificationState)}</small></div><button class="btn" id="enableNotificationsBtn">${icon('notifications')} Enable</button></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="manageSignaturesBtn">${icon('draw')} Signatures</button><button class="btn" id="manageLabelsBtn">${icon('label')} Labels</button><button class="btn" id="manageTemplatesBtn">${icon('article')} Templates</button><button class="btn" id="manageFiltersBtn">${icon('filter_alt')} Filters</button><button class="btn" id="shortcutsBtn">${icon('keyboard')} Shortcuts</button></div>`;openModal('Settings',content,async modal=>{await saveSettings({theme:modal.querySelector('#setTheme').value,density:modal.querySelector('#setDensity').value,keyboard_shortcuts:modal.querySelector('#setShortcuts').value==='true',signature_enabled:modal.querySelector('#setSignatureEnabled').value==='true'});modal.closest('.modal-backdrop').remove();toast('Settings saved','settings');renderApp();},modal=>{modal.querySelector('#setTheme').value=s.theme||'system';modal.querySelector('#setDensity').value=s.density||'comfortable';modal.querySelector('#setShortcuts').value=String(s.keyboard_shortcuts!==false);modal.querySelector('#setSignatureEnabled').value=String(s.signature_enabled!==false);modal.querySelector('#enableNotificationsBtn').onclick=requestNotifications;modal.querySelector('#manageSignaturesBtn').onclick=()=>{modal.closest('.modal-backdrop').remove();openSignatureManager()};modal.querySelector('#manageLabelsBtn').onclick=()=>{modal.closest('.modal-backdrop').remove();openLabelManager()};modal.querySelector('#manageTemplatesBtn').onclick=()=>{modal.closest('.modal-backdrop').remove();openTemplateManager()};modal.querySelector('#manageFiltersBtn').onclick=()=>{modal.closest('.modal-backdrop').remove();openFilterManager()};modal.querySelector('#shortcutsBtn').onclick=()=>{modal.closest('.modal-backdrop').remove();showShortcuts()};});}
async function saveSettings(patch){const row={user_id:currentUser().id,...state.settings,...patch,updated_at:new Date().toISOString()};delete row.created_at;const {data,error}=await supabase.from('frankiflow_mail_settings').upsert(row,{onConflict:'user_id'}).select().single();if(error)return toast(error.message,'error');state.settings=data;applyTheme();}

function showShortcuts(){openModal('Keyboard shortcuts',`<div class="setting-row"><strong>Compose</strong><kbd>C</kbd></div><div class="setting-row"><strong>Search</strong><kbd>/</kbd></div><div class="setting-row"><strong>Next / previous message</strong><kbd>J / K</kbd></div><div class="setting-row"><strong>Archive</strong><kbd>E</kbd></div><div class="setting-row"><strong>Star</strong><kbd>S</kbd></div><div class="setting-row"><strong>Mark unread</strong><kbd>Shift + U</kbd></div><div class="setting-row"><strong>Delete</strong><kbd>#</kbd></div><div class="setting-row"><strong>Command palette</strong><kbd>Ctrl/⌘ + K</kbd></div>`,null);}
function showSearchHelp(){openModal('Power search',`<p class="muted">Combine terms to narrow the current mailbox.</p><div class="setting-row"><strong>from:alex@example.com</strong><small>Sender address</small></div><div class="setting-row"><strong>to:client@example.com</strong><small>Recipient address</small></div><div class="setting-row"><strong>subject:invoice</strong><small>Subject text</small></div><div class="setting-row"><strong>is:unread · is:starred · is:pinned · is:important</strong><small>Status</small></div><div class="setting-row"><strong>has:attachment</strong><small>Only mail with files</small></div><div class="setting-row"><strong>in:inbox · in:archive · in:trash</strong><small>Folder</small></div><div class="setting-row"><strong>before:2026-09-01 · after:2026-09-01</strong><small>Date filters</small></div><div class="setting-row"><strong>label:Clients</strong><small>Messages with a label</small></div>`,null);}
function openModal(title,body,onSave,onReady){closePopover();const back=document.createElement('div');back.className='modal-backdrop';back.innerHTML=`<section class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="icon-btn modalClose">${icon('close')}</button></div><div class="modal-body">${body}</div>${onSave?`<div class="modal-foot"><button class="btn modalCancel">Cancel</button><button class="btn-primary modalSave">Save</button></div>`:''}</section>`;document.body.append(back);const modal=back.querySelector('.modal');back.querySelector('.modalClose').onclick=()=>back.remove();back.querySelector('.modalCancel')?.addEventListener('click',()=>back.remove());back.addEventListener('click',e=>{if(e.target===back)back.remove()});back.querySelector('.modalSave')?.addEventListener('click',()=>onSave(modal));onReady?.(modal);return modal;}

let popoverEl=null;function closePopover(){popoverEl?.remove();popoverEl=null}function showPopover(anchor,items){closePopover();const r=anchor.getBoundingClientRect(),p=document.createElement('div');p.className='popover';p.innerHTML=items.map(([label,ic,,danger])=>`<button class="${danger?'danger':''}">${icon(ic)}${esc(label)}</button>`).join('');document.body.append(p);const pr=p.getBoundingClientRect();p.style.left=`${Math.min(innerWidth-pr.width-8,Math.max(8,r.right-pr.width))}px`;p.style.top=`${Math.min(innerHeight-pr.height-8,r.bottom+6)}px`;[...p.querySelectorAll('button')].forEach((b,i)=>b.onclick=()=>{closePopover();items[i][2]?.()});popoverEl=p;setTimeout(()=>document.addEventListener('click',outsidePopover,{once:true}),0)}function outsidePopover(e){if(popoverEl&&!popoverEl.contains(e.target))closePopover();}

function openCommand(){if(state.commandOpen)return;state.commandOpen=true;const back=document.createElement('div');back.className='modal-backdrop';const commands=[['Compose new email','edit_square',()=>openComposer()],['Go to Inbox','inbox',()=>switchFolder('inbox')],['Go to Sent','send',()=>switchFolder('sent')],['Go to Trash','delete',()=>switchFolder('trash')],['Search mail','search',()=>document.querySelector('#search')?.focus()],['Manage signatures','draw',()=>openSignatureManager()],['Manage labels','label',()=>openLabelManager()],['Email templates','article',()=>openTemplateManager()],['Settings','settings',()=>openSettings()],['Refresh mailbox','refresh',()=>loadAll(true)]];back.innerHTML=`<section class="modal command"><div class="command-search">${icon('search')}<input id="commandInput" placeholder="Type a command…"><kbd>Esc</kbd></div><div class="command-results">${commands.map(([n,ic])=>`<div class="command-item">${icon(ic)}<span>${esc(n)}</span></div>`).join('')}</div></section>`;document.body.append(back);const input=back.querySelector('#commandInput'),items=[...back.querySelectorAll('.command-item')];items.forEach((it,i)=>it.onclick=()=>{back.remove();state.commandOpen=false;commands[i][2]()});input.oninput=()=>items.forEach((it,i)=>it.classList.toggle('hidden',!commands[i][0].toLowerCase().includes(input.value.toLowerCase())));back.onclick=e=>{if(e.target===back){back.remove();state.commandOpen=false}};input.onkeydown=e=>{if(e.key==='Escape'){back.remove();state.commandOpen=false}};input.focus();}

function keyboardHandler(e){if(!state.session||state.commandOpen)return;const target=e.target;if(target.matches('input,textarea,[contenteditable="true"]')){if(e.key==='Escape'&&state.composer)closeComposer();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();return openCommand();}if(e.key==='/'){e.preventDefault();return document.querySelector('#search')?.focus();}if(state.settings?.keyboard_shortcuts===false)return;const k=e.key.toLowerCase();if(k==='c')return openComposer();if(k==='?')return showShortcuts();const list=currentMessages();let i=list.findIndex(m=>m.id===state.activeId);if(k==='j'){i=Math.min(list.length-1,i+1);state.activeId=list[i]?.id;renderList();renderReader();}if(k==='k'){i=Math.max(0,i<=0?0:i-1);state.activeId=list[i]?.id;renderList();renderReader();}const m=state.messages.find(x=>x.id===state.activeId);if(!m)return;if(k==='e')moveMessage(m.id,'archive');if(k==='s')patchMessage(m.id,{is_starred:!m.is_starred});if(e.shiftKey&&k==='u')patchMessage(m.id,{is_read:false});if(e.key==='#')moveMessage(m.id,'trash');}
document.addEventListener('keydown',keyboardHandler);

async function wakeSnoozed(){const due=state.messages.filter(m=>m.folder==='snoozed'&&m.snoozed_until&&new Date(m.snoozed_until)<=new Date()).map(m=>m.id);if(due.length)await supabase.from('frankiflow_mail_messages').update({folder:'inbox',snoozed_until:null,updated_at:new Date().toISOString()}).in('id',due);}
async function loadAll(showToast=false){
  if(!state.session)return;state.loading=true;
  const [m,a,l,ml,c,t,sg,s,f]=await Promise.all([
    supabase.from('frankiflow_mail_messages').select('*').order('created_at',{ascending:false}).limit(1000),
    supabase.from('frankiflow_mail_accounts').select('*').order('is_primary',{ascending:false}),
    supabase.from('frankiflow_mail_labels').select('*').order('name'),
    supabase.from('frankiflow_mail_message_labels').select('*'),
    supabase.from('frankiflow_mail_contacts').select('*').order('last_used_at',{ascending:false}).limit(200),
    supabase.from('frankiflow_mail_templates').select('*').order('name'),
    supabase.from('frankiflow_mail_signatures').select('*').order('is_default',{ascending:false}).order('name'),
    supabase.from('frankiflow_mail_settings').select('*').eq('user_id',currentUser().id).maybeSingle(),
    supabase.from('frankiflow_mail_filters').select('*').order('created_at')
  ]);
  const err=[m,a,l,ml,c,t,sg,s,f].find(x=>x.error)?.error;if(err)return toast(err.message,'error');
  state.messages=m.data||[];state.accounts=a.data||[];state.labels=l.data||[];state.messageLabels=ml.data||[];state.contacts=c.data||[];state.templates=t.data||[];state.signatures=sg.data||[];state.settings=s.data||null;state.filters=f.data||[];
  await wakeSnoozed();await applyFilters();state.loading=false;renderApp();updateDocumentTitle();if(showToast)toast('Mailbox refreshed','refresh');
}

async function requestNotifications(){if(typeof Notification==='undefined')return toast('Desktop notifications are not supported in this browser','warning');if(Notification.permission==='granted')return toast('Desktop notifications are already enabled','notifications_active');const result=await Notification.requestPermission();toast(result==='granted'?'Desktop notifications enabled':'Notifications were not enabled',result==='granted'?'notifications_active':'notifications_off');renderApp();}
function notifyNewMail(m){const who=m.from_name||m.from_address||'New sender';toast(`New mail from ${who}: ${m.subject||'(no subject)'}`,'mark_email_unread');updateDocumentTitle();if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&(document.hidden||!document.hasFocus())){const n=new Notification(`FrankiFlow Mail · ${who}`,{body:m.subject||m.preview||'New email',icon:'/assets/icon.svg',tag:`ffmail-${m.id}`});n.onclick=()=>{window.focus();state.folder='inbox';state.activeId=m.id;renderApp();n.close();};}}
async function setupRealtime(){if(state.realtimeChannel||!state.session)return;state.realtimeChannel=supabase.channel(`frankiflow-mail-live-${currentUser().id}`).on('postgres_changes',{event:'*',schema:'public',table:'frankiflow_mail_messages'},async payload=>{if(payload.eventType==='INSERT'){const row=payload.new;if(!state.messages.some(m=>m.id===row.id))state.messages.unshift(row);if(row.direction==='inbound'&&row.folder==='inbox'){notifyNewMail(row);await applyFilters();}}else if(payload.eventType==='UPDATE'){const i=state.messages.findIndex(m=>m.id===payload.new.id);if(i>=0)state.messages[i]={...state.messages[i],...payload.new};else state.messages.unshift(payload.new);}else if(payload.eventType==='DELETE'){state.messages=state.messages.filter(m=>m.id!==payload.old.id);state.selected.delete(payload.old.id);if(state.activeId===payload.old.id)state.activeId=null;}renderApp();updateDocumentTitle();}).subscribe(status=>{if(status==='CHANNEL_ERROR')toast('Live mailbox connection interrupted','warning');});}
async function teardownRealtime(){if(state.realtimeChannel){await supabase.removeChannel(state.realtimeChannel);state.realtimeChannel=null;}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateDocumentTitle();});

supabase.auth.onAuthStateChange(async(_event,session)=>{state.session=session;if(session){await loadAll();await setupRealtime();}else{await teardownRealtime();loginView();}});
const {data:{session}}=await supabase.auth.getSession();
state.session=session;
if(session){await loadAll();await setupRealtime();}else loginView();
